"""Applies the Android settings Smriti Sathi needs to a project generated by
`flutter create`. Fails loudly if the template changed and a patch no longer
applies, so a broken build is never silent."""
import sys
from pathlib import Path

root = Path(sys.argv[1] if len(sys.argv) > 1 else ".") / "android" / "app"


def patch(path: Path, old: str, new: str) -> None:
    text = path.read_text()
    if old not in text:
        sys.exit(f"patch failed: {old!r} not found in {path}")
    path.write_text(text.replace(old, new, 1))


gradle = root / "build.gradle.kts"
# Release builds shrink and rename code; give R8 the rules the notification plugin needs.
(root / "proguard-rules.pro").write_text(
    (Path(__file__).parent / "proguard-rules.pro").read_text())
patch(gradle, 'signingConfig = signingConfigs.getByName("debug")',
      'signingConfig = signingConfigs.getByName("debug")\n            proguardFiles("proguard-rules.pro")')
patch(gradle, "compileOptions {", "compileOptions {\n        isCoreLibraryDesugaringEnabled = true")
patch(gradle, "minSdk = flutter.minSdkVersion", "minSdk = 23")
patch(gradle, 'applicationId = "com.example.smriti_assist"', 'applicationId = "in.smritisathi.app"')
gradle.write_text(
    gradle.read_text()
    + '\ndependencies {\n    coreLibraryDesugaring("com.android.tools:desugar_jdk_libs:2.1.4")\n}\n'
)

manifest = root / "src" / "main" / "AndroidManifest.xml"
perms = "".join(
    f'    <uses-permission android:name="android.permission.{p}"/>\n'
    for p in (
        "INTERNET",  # the release template only has it in debug builds
        "ACCESS_NETWORK_STATE",
        "RECORD_AUDIO",  # voice notes in chats
        "POST_NOTIFICATIONS",
        "SCHEDULE_EXACT_ALARM",
        "RECEIVE_BOOT_COMPLETED",
        "VIBRATE",
        "CALL_PHONE",
        "ACCESS_COARSE_LOCATION",
        "ACCESS_FINE_LOCATION",
        "FOREGROUND_SERVICE",  # keeps live location sharing going with the screen off
        "FOREGROUND_SERVICE_LOCATION",
        "SEND_SMS",  # live location goes to family by SMS without opening the messaging app
    )
)
patch(manifest, "<application", perms + "    <application", )
patch(manifest, 'android:label="smriti_assist"', 'android:label="Smriti Sathi"\n        android:allowBackup="false"')
patch(
    manifest,
    "</application>",
    """    <receiver android:exported="false" android:name="com.dexterous.flutterlocalnotifications.ScheduledNotificationReceiver"/>
        <receiver android:exported="false" android:name="com.dexterous.flutterlocalnotifications.ScheduledNotificationBootReceiver">
            <intent-filter>
                <action android:name="android.intent.action.BOOT_COMPLETED"/>
                <action android:name="android.intent.action.MY_PACKAGE_REPLACED"/>
            </intent-filter>
        </receiver>
    </application>""",
)
# Firebase push: only when the build has a google-services.json (repository secret
# GOOGLE_SERVICES_JSON). Without it the app builds exactly as before.
if (root / "google-services.json").exists():
    settings = root.parent / "settings.gradle.kts"
    patch(settings, 'id("org.jetbrains.kotlin.android")',
          'id("com.google.gms.google-services") version "4.4.2" apply false\n    id("org.jetbrains.kotlin.android")')
    patch(gradle, 'id("dev.flutter.flutter-gradle-plugin")',
          'id("dev.flutter.flutter-gradle-plugin")\n    id("com.google.gms.google-services")')
    print("Firebase configured")
print("Android patches applied")


# Sends one SMS straight from the phone (no messaging app, no extra tap) for the
# live location. Only SEND_SMS is used: the app never reads messages.
main = next((root / "src" / "main" / "kotlin").rglob("MainActivity.kt"))
package = main.read_text().splitlines()[0]
main.write_text(package + """

import android.os.Build
import android.telephony.SmsManager
import io.flutter.embedding.android.FlutterActivity
import io.flutter.embedding.engine.FlutterEngine
import io.flutter.plugin.common.MethodChannel

class MainActivity : FlutterActivity() {
    override fun configureFlutterEngine(flutterEngine: FlutterEngine) {
        super.configureFlutterEngine(flutterEngine)
        MethodChannel(flutterEngine.dartExecutor.binaryMessenger, "in.smritisathi/sms")
            .setMethodCallHandler { call, result ->
                if (call.method != "send") {
                    result.notImplemented()
                    return@setMethodCallHandler
                }
                val to = call.argument<String>("to")
                val body = call.argument<String>("body")
                if (to == null || body == null) {
                    result.success(false)
                    return@setMethodCallHandler
                }
                try {
                    val sms: SmsManager = if (Build.VERSION.SDK_INT >= 31) {
                        getSystemService(SmsManager::class.java)
                    } else {
                        SmsManager.getDefault()
                    }
                    sms.sendMultipartTextMessage(to, null, sms.divideMessage(body), null, null)
                    result.success(true)
                } catch (e: Exception) {
                    result.success(false)
                }
            }
    }
}
""")
print("MainActivity patched")
